  const lowered = input.toLowerCase();
  const uppered = input.toUpperCase();
  assert.sameValue(lowered, lower, "lowercase text");
  assert.sameValue(lowered.length, lower.length, "lowercase UTF-16 length");
  assert.sameValue(uppered, upper, "uppercase text");
